import { GeometryEngine } from '../core/GeometryEngine';
import { SelectionModel } from '../core/SelectionModel';
import { StreamingEngine } from '../core/StreamingEngine';
import { IDataStore } from '../types/store';
import { IGridThemeTokens } from '../theme/IGridTheme';
import { ColumnTypeRegistry } from '../columns/ColumnTypeRegistry';
import { SkeletonPainter } from './SkeletonPainter';
import { SortDescriptor } from '../types/filter';
import { IGridLocale } from '../i18n/IGridLocale';
import { ColumnDef, ColumnGroupDef, GridPermissions, RowSelectionMode } from '../types/grid';
import {
  ColumnColorEngine,
  ResolvedColumnStyle,
  ResolvedGroupHeaderStyle,
} from '../theme/ColumnColorEngine';

export interface RenderParams {
  canvas: HTMLCanvasElement;
  geometry: GeometryEngine;
  store: IDataStore;
  selection: SelectionModel;
  theme: IGridThemeTokens;
  locale: IGridLocale;
  scrollLeft: number;
  scrollTop: number;
  sortRules: SortDescriptor[];
  searchKeyword?: string;
  hoveredCell?: { row: number; col: number } | null;
  hoveredFilterColIndex?: number | null;
  activeFilterColumnIds?: Set<string>;
  fillDragRange?: { minRow: number; maxRow: number; minCol: number; maxCol: number } | null;
  loadingRowKeys?: Set<any>;
  permissions?: GridPermissions;
  selectionMode?: RowSelectionMode;
  selectedRowKeys?: Set<any>;
  zebraStriping?: boolean | string | { light: string; dark: string };
  streamingEngine?: StreamingEngine | null;
  getRowStyle?: (row: Record<string, any>, rowIndex: number) => { backgroundColor?: string; textColor?: string } | undefined;
}

export class CanvasRenderer {
  public static isColumnReadonly(col: ColumnDef, permissions?: GridPermissions): boolean {
    if (permissions?.mode === 'read' || permissions?.mode === 'readonly') return true;
    if (permissions?.allowUpdating === false) return true;
    if (col.readonly || col.permission === 'readonly' || col.permission === 'read') return true;
    return false;
  }

  public static render(params: RenderParams): void {
    const {
      canvas,
      geometry,
      store,
      selection,
      theme,
      locale,
      scrollLeft,
      scrollTop,
      sortRules,
      searchKeyword,
      hoveredCell,
      hoveredFilterColIndex,
      activeFilterColumnIds,
      fillDragRange,
      loadingRowKeys,
      permissions,
      selectionMode = 'none',
      selectedRowKeys,
      zebraStriping = true,
      streamingEngine,
      getRowStyle,
    } = params;

    const now = performance.now();

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1;
    const rect = canvas.getBoundingClientRect();
    const width = Math.round(rect.width) || canvas.clientWidth || 0;
    const height = Math.round(rect.height) || canvas.clientHeight || 0;

    if (width <= 0 || height <= 0) return;

    const targetPixelWidth = Math.round(width * dpr);
    const targetPixelHeight = Math.round(height * dpr);

    if (canvas.width !== targetPixelWidth || canvas.height !== targetPixelHeight) {
      canvas.width = targetPixelWidth;
      canvas.height = targetPixelHeight;
    }

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.save();
    ctx.scale(dpr, dpr);

    try {
      // 1. Background Fill
      ctx.fillStyle = theme.canvas.bg;
      ctx.fillRect(0, 0, width, height);

      const rowCount = store.getRowCount();
      const rowH = geometry.rowHeight;
      const headerH = geometry.headerHeight;
      const rowNumW = geometry.rowNumberWidth;

      // 2. Viewport Row Bounds
      const startRow = Math.max(0, Math.floor(scrollTop / rowH));
      const endRow = Math.min(rowCount - 1, Math.ceil((scrollTop + height - headerH) / rowH));

      if (rowCount > 0 && endRow >= startRow) {
        store.ensureRange(startRow, endRow);
      } else if (rowCount === 0 && store.isRemote()) {
        store.ensureRange(0, Math.max(0, Math.ceil((height - headerH) / rowH)));
      }

      const totalLeftPinnedWidth = geometry.totalLeftPinnedWidth;
      const rightPinnedStartX = geometry.getRightPinnedStartX();
      const centerClipWidth = Math.max(0, rightPinnedStartX - totalLeftPinnedWidth);
      const rightClipWidth = Math.max(0, width - rightPinnedStartX);

      // 3. Viewport Center Column Bounds
      let startCenterColIdx = 0;
      let endCenterColIdx = geometry.centerColumns.length - 1;

      if (geometry.centerColumns.length > 0) {
        startCenterColIdx = geometry.findCenterColIndexAtX(scrollLeft);
        endCenterColIdx = geometry.findCenterColIndexAtX(
          scrollLeft + centerClipWidth
        );
      }

      const normSel = selection.getNormalizedRange();
      const resolvedZebraBg =
        zebraStriping === false
          ? undefined
          : typeof zebraStriping === 'string'
            ? zebraStriping
            : typeof zebraStriping === 'object' && zebraStriping !== null
              ? theme.isDark
                ? zebraStriping.dark
                : zebraStriping.light
              : theme.canvas.zebraRowBg || (theme.isDark ? '#232428' : '#F4F7FB');
      const resolvedRowHoverBg =
        theme.canvas.rowHoverBg ||
        (theme.isDark ? 'rgba(10, 132, 255, 0.06)' : 'rgba(0, 122, 255, 0.035)');

      // ========================================================================
      // SKELETONS & GROUP ROWS (Full Width Passes)
      // ========================================================================
      for (let r = startRow; r <= endRow; r++) {
        const rowY = headerH + r * rowH - scrollTop;
        const vRow = store.getViewRow(r);

        const isSkeletonRow = !vRow || Boolean((vRow as any)?.data?.__isLoading || (vRow as any)?.__isLoading);

        if (isSkeletonRow) {
          // 1. CENTER SCROLLABLE COLUMNS SKELETON
          if (geometry.centerColumns.length > 0 && centerClipWidth > 0) {
            ctx.save();
            ctx.beginPath();
            ctx.rect(
              totalLeftPinnedWidth,
              headerH,
              centerClipWidth,
              Math.max(0, height - headerH)
            );
            ctx.clip();

            for (let sc = startCenterColIdx; sc <= endCenterColIdx; sc++) {
              const col = geometry.centerColumns[sc];
              if (!col) continue;

              const cellX = totalLeftPinnedWidth + geometry.centerColOffsets[sc] - scrollLeft;
              SkeletonPainter.paintSkeletonCell(ctx, cellX, rowY, col.width, rowH, theme);
            }
            ctx.restore();
          }

          // 2. LEFT PINNED COLUMNS SKELETON
          let curLeftX = rowNumW;
          for (let lc = 0; lc < geometry.leftPinnedColumns.length; lc++) {
            const col = geometry.leftPinnedColumns[lc];
            SkeletonPainter.paintSkeletonCell(ctx, curLeftX, rowY, col.width, rowH, theme);
            curLeftX += col.width;
          }

          // 3. RIGHT PINNED COLUMNS SKELETON
          if (geometry.rightPinnedColumns.length > 0 && rightClipWidth > 0) {
            ctx.save();
            ctx.beginPath();
            ctx.rect(
              rightPinnedStartX,
              headerH,
              rightClipWidth,
              Math.max(0, height - headerH)
            );
            ctx.clip();

            for (let rc = 0; rc < geometry.rightPinnedColumns.length; rc++) {
              const col = geometry.rightPinnedColumns[rc];
              const cellX = rightPinnedStartX + geometry.rightColOffsets[rc];
              SkeletonPainter.paintSkeletonCell(ctx, cellX, rowY, col.width, rowH, theme);
            }
            ctx.restore();
          }

          // 4. ROW NUMBER GUTTER SKELETON
          ctx.fillStyle = theme.canvas.rowNumberBg;
          ctx.fillRect(0, rowY, rowNumW, rowH);

          ctx.fillStyle = '#FF9F0A';
          ctx.fillRect(0, rowY, 3, rowH);

          ctx.fillStyle = theme.canvas.rowNumberText;
          ctx.font = '500 ' + (theme.fontSize - 1) + 'px ' + theme.fontFamily;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText('⟳', rowNumW / 2, rowY + rowH / 2);

          ctx.strokeStyle = theme.canvas.rowNumberBorder;
          ctx.beginPath();
          ctx.moveTo(rowNumW - 0.5, rowY);
          ctx.lineTo(rowNumW - 0.5, rowY + rowH);
          ctx.moveTo(0, rowY + rowH - 0.5);
          ctx.lineTo(rowNumW, rowY + rowH - 0.5);
          ctx.stroke();

          continue;
        }
      }

      // ========================================================================
      // 3-PASS DUAL PINNING DATA CELL RENDERING
      // ========================================================================

      // --- PASS 1 (Center Scrollable) ---
      if (geometry.centerColumns.length > 0 && centerClipWidth > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(totalLeftPinnedWidth, headerH, centerClipWidth, Math.max(0, height - headerH));
        ctx.clip();

        for (let r = startRow; r <= endRow; r++) {
          const vRow = store.getViewRow(r);
          if (!vRow || vRow.type !== 'data') continue;

          const rowData = vRow.data;
          const rowKey = rowData.id ?? r;
          const isRowInserted = store.isRowInserted?.(rowKey) ?? false;
          const isRowLoading = loadingRowKeys?.has(rowKey) ?? false;
          const rowY = headerH + r * rowH - scrollTop;
          const isZebraRow = Boolean(resolvedZebraBg && r % 2 === 1);
          const isRowHovered = hoveredCell?.row === r;
          const customRowStyle = getRowStyle ? getRowStyle(rowData, r) : undefined;

          if (customRowStyle?.backgroundColor) {
            ctx.fillStyle = customRowStyle.backgroundColor;
            ctx.fillRect(totalLeftPinnedWidth, rowY, centerClipWidth, rowH);
          } else if (isZebraRow && resolvedZebraBg) {
            ctx.fillStyle = resolvedZebraBg;
            ctx.fillRect(totalLeftPinnedWidth, rowY, centerClipWidth, rowH);
          }
          if (isRowHovered) {
            ctx.fillStyle = resolvedRowHoverBg;
            ctx.fillRect(totalLeftPinnedWidth, rowY, centerClipWidth, rowH);
          }

          for (let sc = startCenterColIdx; sc <= endCenterColIdx; sc++) {
            const col = geometry.centerColumns[sc];
            if (!col) continue;

            const colIdx = geometry.leftPinnedColumns.length + sc;
            const cellX = totalLeftPinnedWidth + geometry.centerColOffsets[sc] - scrollLeft;
            const colStyle = ColumnColorEngine.resolveColumnStyle(
              col,
              geometry.getColumnGroup(col),
              theme.isDark
            );
            this.renderCell(
              ctx,
              rowData,
              rowKey,
              r,
              col,
              colIdx,
              cellX,
              rowY,
              col.width,
              rowH,
              theme,
              locale,
              selection,
              store,
              hoveredCell,
              searchKeyword,
              isRowInserted,
              isRowLoading,
              permissions,
              selectionMode,
              selectedRowKeys,
              colStyle,
              streamingEngine,
              now,
              customRowStyle
            );
          }
        }
        ctx.restore();
      }

      // --- PASS 2 (Left Pinned Columns & Row Numbers) ---
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, headerH, totalLeftPinnedWidth, Math.max(0, height - headerH));
      ctx.clip();

      for (let r = startRow; r <= endRow; r++) {
        const vRow = store.getViewRow(r);
        if (!vRow || vRow.type !== 'data') continue;

        const rowData = vRow.data;
        const rowKey = rowData.uuid ?? rowData.id ?? r;
        const isRowInserted = store.isRowInserted?.(rowKey) ?? false;
        const isRowLoading = loadingRowKeys?.has(rowKey) ?? false;
        const isRowInActiveSel = r >= normSel.minRow && r <= normSel.maxRow;
        const isZebraRow = Boolean(resolvedZebraBg && r % 2 === 1);
        const isRowHovered = hoveredCell?.row === r;
        const rowY = headerH + r * rowH - scrollTop;
        const customRowStyle = getRowStyle ? getRowStyle(rowData, r) : undefined;

        // Render Left Pinned Cells
        let curLeftX = rowNumW;
        for (let lc = 0; lc < geometry.leftPinnedColumns.length; lc++) {
          const col = geometry.leftPinnedColumns[lc];
          if (customRowStyle?.backgroundColor) {
            ctx.fillStyle = customRowStyle.backgroundColor;
            ctx.fillRect(curLeftX, rowY, col.width, rowH);
          } else {
            ctx.fillStyle = isZebraRow && resolvedZebraBg ? resolvedZebraBg : theme.canvas.bg;
            ctx.fillRect(curLeftX, rowY, col.width, rowH);
          }
          if (isRowHovered) {
            ctx.fillStyle = resolvedRowHoverBg;
            ctx.fillRect(curLeftX, rowY, col.width, rowH);
          }

          const colStyle = ColumnColorEngine.resolveColumnStyle(
            col,
            geometry.getColumnGroup(col),
            theme.isDark
          );
          this.renderCell(
            ctx,
            rowData,
            rowKey,
            r,
            col,
            lc,
            curLeftX,
            rowY,
            col.width,
            rowH,
            theme,
            locale,
            selection,
            store,
            hoveredCell,
            searchKeyword,
            isRowInserted,
            isRowLoading,
            permissions,
            selectionMode,
            selectedRowKeys,
            colStyle,
            streamingEngine,
            now,
            customRowStyle
          );
          curLeftX += col.width;
        }

        // Row Number Gutter (Leftmost)
        ctx.fillStyle = isRowInActiveSel
          ? theme.isDark
            ? 'rgba(10, 132, 255, 0.22)'
            : 'rgba(0, 122, 255, 0.12)'
          : isZebraRow
          ? theme.isDark
            ? '#202124'
            : '#EEF2F7'
          : theme.canvas.rowNumberBg;
        ctx.fillRect(0, rowY, rowNumW, rowH);

        if (isRowInserted) {
          ctx.fillStyle = '#30D158';
          ctx.fillRect(0, rowY, 4, rowH);
        } else if (isRowLoading) {
          ctx.fillStyle = '#FF9F0A';
          ctx.fillRect(0, rowY, 4, rowH);
        }

        ctx.fillStyle = isRowInActiveSel ? theme.dom.accentColor : theme.canvas.rowNumberText;
        ctx.font = `${isRowInActiveSel ? '700' : '500'} ${theme.fontSize - 1}px ${theme.fontFamily}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(isRowLoading ? '⟳' : String(r + 1), rowNumW / 2, rowY + rowH / 2);

        // Row number border
        ctx.strokeStyle = theme.canvas.rowNumberBorder;
        ctx.beginPath();
        ctx.moveTo(rowNumW - 0.5, rowY);
        ctx.lineTo(rowNumW - 0.5, rowY + rowH);
        ctx.moveTo(0, rowY + rowH - 0.5);
        ctx.lineTo(rowNumW, rowY + rowH - 0.5);
        ctx.stroke();
      }

      // Fixed vertical divider shadow on right edge of Left Pinned zone
      if (geometry.leftPinnedColumns.length > 0) {
        ctx.fillStyle = theme.canvas.frozenDividerShadow;
        ctx.fillRect(totalLeftPinnedWidth - 1, headerH, 3, height - headerH);
      }
      ctx.restore();

      // --- PASS 3 (Right Pinned Columns) ---
      if (geometry.rightPinnedColumns.length > 0 && rightClipWidth > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(rightPinnedStartX, headerH, rightClipWidth, Math.max(0, height - headerH));
        ctx.clip();

        const baseRightIdx = geometry.leftPinnedColumns.length + geometry.centerColumns.length;
        for (let r = startRow; r <= endRow; r++) {
          const vRow = store.getViewRow(r);
          if (!vRow || vRow.type !== 'data') continue;

          const rowData = vRow.data;
          const rowKey = rowData.id ?? r;
          const isRowInserted = store.isRowInserted?.(rowKey) ?? false;
          const isRowLoading = loadingRowKeys?.has(rowKey) ?? false;
          const rowY = headerH + r * rowH - scrollTop;
          const isZebraRow = Boolean(resolvedZebraBg && r % 2 === 1);
          const isRowHovered = hoveredCell?.row === r;
          const customRowStyle = getRowStyle ? getRowStyle(rowData, r) : undefined;

          for (let rc = 0; rc < geometry.rightPinnedColumns.length; rc++) {
            const col = geometry.rightPinnedColumns[rc];
            const colIdx = baseRightIdx + rc;
            const cellX = rightPinnedStartX + geometry.rightColOffsets[rc];

            if (customRowStyle?.backgroundColor) {
              ctx.fillStyle = customRowStyle.backgroundColor;
              ctx.fillRect(cellX, rowY, col.width, rowH);
            } else {
              ctx.fillStyle = isZebraRow && resolvedZebraBg ? resolvedZebraBg : theme.canvas.bg;
              ctx.fillRect(cellX, rowY, col.width, rowH);
            }
            if (isRowHovered) {
              ctx.fillStyle = resolvedRowHoverBg;
              ctx.fillRect(cellX, rowY, col.width, rowH);
            }

            const colStyle = ColumnColorEngine.resolveColumnStyle(
              col,
              geometry.getColumnGroup(col),
              theme.isDark
            );
            this.renderCell(
              ctx,
              rowData,
              rowKey,
              r,
              col,
              colIdx,
              cellX,
              rowY,
              col.width,
              rowH,
              theme,
              locale,
              selection,
              store,
              hoveredCell,
              searchKeyword,
              isRowInserted,
              isRowLoading,
              permissions,
              selectionMode,
              selectedRowKeys,
              colStyle,
              streamingEngine,
              now,
              customRowStyle
            );
          }
        }

        // Subtle drop shadow / vertical separator line on left edge of Right Pinned zone
        ctx.fillStyle = theme.canvas.frozenDividerShadow;
        ctx.fillRect(rightPinnedStartX - 2, headerH, 3, height - headerH);
        ctx.restore();
      }

      // --- PASS 3.5 (Full-Width Group Header Bands Over Pinned Zones) ---
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, headerH, width, Math.max(0, height - headerH));
      ctx.clip();

      for (let r = startRow; r <= endRow; r++) {
        const vRow = store.getViewRow(r);
        if (!vRow) continue;
        if (vRow.type === 'group' || (vRow as any).__isGroup || (vRow as any).data?.__isGroup) {
          const rowY = headerH + r * rowH - scrollTop;
          const groupData = (vRow as any)?.__isGroup
            ? (vRow as any)
            : (vRow as any)?.data?.__isGroup
            ? (vRow as any).data
            : vRow;

          CanvasRenderer.paintGroupRowBand(
            ctx,
            groupData,
            rowY,
            width,
            rowH,
            theme,
            locale,
            geometry.columns,
            hoveredCell?.row === r,
            rowNumW
          );
        }
      }
      ctx.restore();

      // ========================================================================
      // FILL HANDLE DRAG PREVIEW RECTANGLE (Excel AutoFill Dashed Box)
      // ========================================================================
      if (fillDragRange && rowCount > 0) {
        const fTopY = headerH + fillDragRange.minRow * rowH - scrollTop;
        const fHeight = (fillDragRange.maxRow - fillDragRange.minRow + 1) * rowH;
        const fLeftRect = geometry.getColumnScreenRect(fillDragRange.minCol, scrollLeft);
        const fRightRect = geometry.getColumnScreenRect(fillDragRange.maxCol, scrollLeft);

        if (fLeftRect && fRightRect) {
          const fLeftX = fLeftRect.x;
          const fWidth = fRightRect.x + fRightRect.width - fLeftRect.x;

          ctx.save();
          ctx.beginPath();
          ctx.rect(rowNumW, headerH, width - rowNumW, height - headerH);
          ctx.clip();

          ctx.fillStyle = theme.isDark ? 'rgba(48, 209, 88, 0.14)' : 'rgba(52, 199, 89, 0.12)';
          ctx.fillRect(fLeftX, fTopY, fWidth, fHeight);

          ctx.strokeStyle = theme.isDark ? '#30D158' : '#28CD41';
          ctx.lineWidth = 2;
          ctx.setLineDash([5, 3]);
          ctx.strokeRect(fLeftX, fTopY, fWidth, fHeight);
          ctx.restore();
        }
      }

      // ========================================================================
      // SELECTION HIGHLIGHT, CORNER FILL HANDLE & RIGHT DUPLICATE HANDLE
      // ========================================================================
      const activeViewRowForSel = store.getViewRow(normSel.minRow);
      const isSingleGroupRowSelected =
        normSel.minRow === normSel.maxRow && activeViewRowForSel?.type === 'group';

      if (
        !isSingleGroupRowSelected &&
        rowCount > 0 &&
        normSel.minRow <= endRow &&
        normSel.maxRow >= startRow
      ) {
        const rTopY = headerH + normSel.minRow * rowH - scrollTop;
        const rHeight = (normSel.maxRow - normSel.minRow + 1) * rowH;

        const leftColRect = geometry.getColumnScreenRect(normSel.minCol, scrollLeft);
        const rightColRect = geometry.getColumnScreenRect(normSel.maxCol, scrollLeft);

        if (leftColRect && rightColRect) {
          const rLeftX = leftColRect.x;
          const rWidth = rightColRect.x + rightColRect.width - leftColRect.x;

          ctx.save();
          ctx.beginPath();
          ctx.rect(rowNumW, headerH, width - rowNumW, height - headerH);
          ctx.clip();

          // Selection translucent fill
          ctx.fillStyle = theme.canvas.selectionFill;
          ctx.fillRect(rLeftX, rTopY, rWidth, rHeight);

          // Selection border
          ctx.strokeStyle = theme.canvas.selectionBorder;
          ctx.lineWidth = 2;
          ctx.strokeRect(rLeftX, rTopY, rWidth, rHeight);

          const activeColDef = geometry.columns[normSel.maxCol];
          const activeColType = (activeColDef?.type || '').toLowerCase();
          const isSpecialNonDuplicatable =
            !activeColDef ||
            activeColType === 'sparkline' ||
            activeColType === 'action' ||
            activeColType === 'dropdownbutton' ||
            activeColType === 'pdf' ||
            this.isColumnReadonly(activeColDef, permissions);

          const canDuplicate =
            !isSpecialNonDuplicatable &&
            permissions?.mode !== 'read' &&
            permissions?.mode !== 'readonly' &&
            permissions?.allowUpdating !== false &&
            permissions?.allowDuplicating !== false;

          if (canDuplicate) {
            // 1. Bottom-Right Corner Fill Handle (Excel Square)
            const fhSize = 8;
            const fhX = rLeftX + rWidth - fhSize / 2;
            const fhY = rTopY + rHeight - fhSize / 2;
            ctx.fillStyle = theme.canvas.fillHandleColor;
            ctx.fillRect(fhX, fhY, fhSize, fhSize);
            ctx.strokeStyle = theme.canvas.bg;
            ctx.lineWidth = 1.5;
            ctx.strokeRect(fhX, fhY, fhSize, fhSize);

            // 2. Right-Side Quick Cell Duplicate Handle ("+" pill on right edge)
            const dupSize = 14;
            const dupX = rLeftX + rWidth - dupSize / 2;
            const dupY = rTopY + rHeight / 2 - dupSize / 2;

            ctx.fillStyle = theme.dom.accentColor;
            ctx.beginPath();
            ctx.roundRect(dupX, dupY, dupSize, dupSize, 4);
            ctx.fill();

            ctx.strokeStyle = theme.canvas.bg;
            ctx.lineWidth = 1.2;
            ctx.stroke();

            // Draw tiny '+' inside the right duplicate handle
            const cx = dupX + dupSize / 2;
            const cy = dupY + dupSize / 2;
            ctx.strokeStyle = '#FFFFFF';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(cx - 3, cy);
            ctx.lineTo(cx + 3, cy);
            ctx.moveTo(cx, cy - 3);
            ctx.lineTo(cx, cy + 3);
            ctx.stroke();
          }

          ctx.restore();
        }
      }

      // ========================================================================
      // EMPTY STATE (WHEN ROW COUNT === 0)
      // ========================================================================
      if (rowCount === 0) {
        const isTR = locale.code.startsWith('tr');
        // Draw subtle faint grid lines in background
        ctx.strokeStyle = theme.canvas.gridLine;
        ctx.lineWidth = 1;
        const maxEmptyRows = Math.floor((height - headerH) / rowH);
        for (let er = 1; er <= maxEmptyRows; er++) {
          const ey = headerH + er * rowH - 0.5;
          ctx.beginPath();
          ctx.moveTo(0, ey);
          ctx.lineTo(width, ey);
          ctx.stroke();
        }

        // Draw Empty State Card in center of viewport
        const cardW = Math.min(440, width - 40);
        const cardH = 110;
        const cardX = Math.max(20, (width - cardW) / 2);
        const cardY = Math.max(headerH + 20, headerH + (height - headerH - cardH) / 2);

        ctx.save();
        ctx.fillStyle = theme.isDark ? 'rgba(17, 24, 39, 0.92)' : 'rgba(255, 255, 255, 0.95)';
        ctx.strokeStyle = theme.canvas.headerBorder;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.roundRect(cardX, cardY, cardW, cardH, 12);
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = theme.dom.accentColor;
        ctx.font = `700 14px ${theme.fontFamily}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(
          isTR ? 'Tabloda Görüntülenecek Veri Bulunmuyor (0 Satır)' : 'No Records to Display (0 Rows)',
          cardX + cardW / 2,
          cardY + 38
        );

        ctx.fillStyle = theme.canvas.rowNumberText;
        ctx.font = `500 12px ${theme.fontFamily}`;
        ctx.fillText(
          isTR
            ? "Yeni kayıt oluşturmak için üstteki '+ Satır Ekle' butonunu veya Sihirbazı kullanın."
            : "Click '+ Add Row' in the toolbar or use the Studio Wizard to populate records.",
          cardX + cardW / 2,
          cardY + 68
        );
        ctx.restore();
      }

      // ========================================================================
      // COLUMN HEADERS (FIXED AT TOP)
      // ========================================================================
      this.renderHeaders(
        ctx,
        geometry,
        store,
        theme,
        scrollLeft,
        width,
        headerH,
        rowNumW,
        sortRules,
        normSel,
        hoveredFilterColIndex,
        activeFilterColumnIds,
        permissions,
        selectionMode,
        selectedRowKeys
      );
    } finally {
      ctx.restore();
    }
  }

  private static renderCell(
    ctx: CanvasRenderingContext2D,
    rowData: Record<string, any>,
    rowKey: any,
    rowIndex: number,
    col: ColumnDef,
    colIdx: number,
    cellX: number,
    rowY: number,
    colW: number,
    rowH: number,
    theme: IGridThemeTokens,
    locale: IGridLocale,
    selection: SelectionModel,
    store: IDataStore,
    hoveredCell?: { row: number; col: number } | null,
    searchKeyword?: string,
    isRowInserted?: boolean,
    isRowLoading?: boolean,
    permissions?: GridPermissions,
    selectionMode: RowSelectionMode = 'none',
    selectedRowKeys?: Set<any>,
    colStyle?: ResolvedColumnStyle,
    streamingEngine?: StreamingEngine | null,
    now: number = 0,
    customRowStyle?: { backgroundColor?: string; textColor?: string }
  ): void {
    const cellVal = typeof rowData[col.id] === 'function' ? undefined : rowData[col.id];
    const isHovered = hoveredCell?.row === rowIndex && hoveredCell?.col === colIdx;
    const isRowSelectedByCheck = selectedRowKeys?.has(rowKey) ?? false;
    const isReadonly =
      this.isColumnReadonly(col, permissions) ||
      (col.canEdit ? !col.canEdit(rowData, col) : false);
    const isDirty = store.isCellDirty?.(rowKey, col.id) ?? false;
    const isInvalid = (store as any).isCellInvalid?.(rowKey, col.id) ?? false;
    const isColDirty = store.isColumnDirty?.(col.id) ?? false;

    // Custom row style background (e.g. expired warning row), fallback to theme-aware column cell background
    if (col.id !== '__selection__') {
      if (customRowStyle?.backgroundColor) {
        ctx.fillStyle = customRowStyle.backgroundColor;
        ctx.fillRect(cellX, rowY, colW, rowH);
      } else if (colStyle?.columnBg) {
        ctx.fillStyle = colStyle.columnBg;
        ctx.fillRect(cellX, rowY, colW, rowH);
      }
    }

    // Row selection tint when selected via Single / Multiple Choice
    if (isRowSelectedByCheck) {
      ctx.fillStyle = theme.isDark ? 'rgba(56, 189, 248, 0.14)' : 'rgba(2, 132, 199, 0.10)';
      ctx.fillRect(cellX, rowY, colW, rowH);
    }

    // Synthetic Row Selection Column ('__selection__')
    if (col.id === '__selection__') {
      const cx = cellX + colW / 2;
      const cy = rowY + rowH / 2;
      ctx.save();
      if (selectionMode === 'single') {
        const radius = 7.5;
        ctx.beginPath();
        ctx.arc(cx, cy, radius, 0, Math.PI * 2);
        ctx.fillStyle = isRowSelectedByCheck
          ? theme.isDark
            ? 'rgba(56, 189, 248, 0.2)'
            : 'rgba(2, 132, 199, 0.15)'
          : theme.dom.inputBg;
        ctx.fill();
        ctx.lineWidth = 1.6;
        ctx.strokeStyle = isRowSelectedByCheck ? theme.dom.accentColor : theme.canvas.headerBorder;
        ctx.stroke();

        if (isRowSelectedByCheck) {
          ctx.beginPath();
          ctx.arc(cx, cy, 4, 0, Math.PI * 2);
          ctx.fillStyle = theme.dom.accentColor;
          ctx.fill();
        }
      } else {
        const boxSize = 15;
        const bx = cx - boxSize / 2;
        const by = cy - boxSize / 2;
        ctx.beginPath();
        ctx.roundRect(bx, by, boxSize, boxSize, 4);
        if (isRowSelectedByCheck) {
          ctx.fillStyle = theme.dom.accentColor;
          ctx.fill();
          ctx.strokeStyle = '#FFFFFF';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(bx + 3.5, cy);
          ctx.lineTo(bx + 6.5, cy + 3);
          ctx.lineTo(bx + 11.5, cy - 3);
          ctx.stroke();
        } else {
          ctx.fillStyle = theme.dom.inputBg;
          ctx.fill();
          ctx.strokeStyle = isHovered ? theme.dom.accentColor : theme.canvas.headerBorder;
          ctx.lineWidth = 1.4;
          ctx.stroke();
        }
      }
      ctx.restore();

      // Cell Grid Lines
      ctx.strokeStyle = theme.canvas.gridLine;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(cellX + colW - 0.5, rowY);
      ctx.lineTo(cellX + colW - 0.5, rowY + rowH);
      ctx.moveTo(cellX, rowY + rowH - 0.5);
      ctx.lineTo(cellX + colW, rowY + rowH - 0.5);
      ctx.stroke();
      return;
    }

    // DevExtreme-style background for dirty cells (dx-cell-modified), invalid cells (dx-cell-invalid), dirty columns, inserted rows, loading, or readonly
    if (isRowLoading) {
      ctx.fillStyle = theme.isDark ? 'rgba(255, 159, 10, 0.14)' : 'rgba(255, 149, 0, 0.10)';
      ctx.fillRect(cellX, rowY, colW, rowH);
    } else if (isInvalid) {
      // DevExtreme dx-cell-invalid distinct warning/error red highlight
      ctx.fillStyle = theme.isDark ? 'rgba(239, 68, 68, 0.28)' : 'rgba(239, 68, 68, 0.18)';
      ctx.fillRect(cellX, rowY, colW, rowH);
    } else if (isDirty) {
      // DevExtreme dx-cell-modified distinct green highlight
      ctx.fillStyle = theme.isDark ? 'rgba(34, 197, 94, 0.22)' : 'rgba(22, 163, 74, 0.15)';
      ctx.fillRect(cellX, rowY, colW, rowH);
    } else if (isRowInserted) {
      // DevExtreme dx-row-inserted highlight
      ctx.fillStyle = theme.isDark ? 'rgba(48, 209, 88, 0.10)' : 'rgba(52, 199, 89, 0.08)';
      ctx.fillRect(cellX, rowY, colW, rowH);
    } else if (isColDirty) {
      // Subtle column-wide tint when this column has uncommitted modifications
      ctx.fillStyle = theme.isDark ? 'rgba(34, 197, 94, 0.05)' : 'rgba(22, 163, 74, 0.04)';
      ctx.fillRect(cellX, rowY, colW, rowH);
    }

    // Search keyword highlight
    if (
      searchKeyword &&
      cellVal != null &&
      String(cellVal).toLowerCase().includes(searchKeyword.toLowerCase())
    ) {
      ctx.fillStyle = theme.canvas.searchHighlight;
      ctx.fillRect(cellX, rowY, colW, rowH);
    }

    // Real-time Streaming Cell Flash / Pulse Effect
    if (streamingEngine) {
      const flash = streamingEngine.getFlash(rowKey, col.id, now);
      if (flash && flash.opacity > 0) {
        ctx.save();
        const alpha = flash.opacity;
        const flashColor =
          flash.type === 'up'
            ? `rgba(48, 209, 88, ${alpha})`
            : flash.type === 'down'
            ? `rgba(255, 69, 58, ${alpha})`
            : `rgba(10, 132, 255, ${alpha})`;
        ctx.fillStyle = flashColor;
        ctx.fillRect(cellX, rowY, colW, rowH);
        ctx.restore();
      }
    }

    // Column type plugin paint (with optional theme-aware columnText or customRowStyle override)
    const effectiveTextColor = customRowStyle?.textColor || colStyle?.columnText;
    const effectiveTheme = effectiveTextColor
      ? {
          ...theme,
          canvas: {
            ...theme.canvas,
            cellText: effectiveTextColor,
          },
        }
      : theme;
    const plugin = ColumnTypeRegistry.get(col.type);
    plugin.paint({
      ctx,
      value: cellVal,
      row: rowData,
      rowIndex,
      column: col,
      theme: effectiveTheme,
      locale,
      x: cellX,
      y: rowY,
      width: colW,
      height: rowH,
      isSelected: selection.isCellSelected(rowIndex, colIdx),
      isHovered,
      isReadonly,
      isDirty,
    });

    // DevExtreme dx-cell-invalid / dx-cell-modified Crisp Border + Top-Right Triangle Indicator
    if (isInvalid) {
      ctx.save();
      const invalidStroke = '#EF4444';
      ctx.strokeStyle = invalidStroke;
      ctx.lineWidth = 2;
      ctx.strokeRect(cellX + 1, rowY + 1, colW - 2, rowH - 2);

      ctx.fillStyle = invalidStroke;
      ctx.beginPath();
      ctx.moveTo(cellX + colW - 9, rowY);
      ctx.lineTo(cellX + colW, rowY);
      ctx.lineTo(cellX + colW, rowY + 9);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    } else if (isDirty) {
      ctx.save();
      const dirtyStroke = theme.isDark ? '#22C55E' : '#16A34A';
      ctx.strokeStyle = dirtyStroke;
      ctx.lineWidth = 1.5;
      ctx.strokeRect(cellX + 0.75, rowY + 0.75, colW - 1.5, rowH - 1.5);

      ctx.fillStyle = dirtyStroke;
      ctx.beginPath();
      ctx.moveTo(cellX + colW - 8, rowY);
      ctx.lineTo(cellX + colW, rowY);
      ctx.lineTo(cellX + colW, rowY + 8);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    // Cell Grid Lines
    ctx.strokeStyle = theme.canvas.gridLine;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cellX + colW - 0.5, rowY);
    ctx.lineTo(cellX + colW - 0.5, rowY + rowH);
    ctx.moveTo(cellX, rowY + rowH - 0.5);
    ctx.lineTo(cellX + colW, rowY + rowH - 0.5);
    ctx.stroke();
  }

  /**
   * Draws a pixel-crisp Google Material Symbols style lock icon (11x12 px) on HTML5 Canvas.
   */
  public static drawGoogleLockIcon(
    ctx: CanvasRenderingContext2D,
    x: number,
    centerY: number,
    color: string
  ): void {
    ctx.save();
    ctx.fillStyle = color;
    ctx.strokeStyle = color;
    const iconTop = centerY - 5.5;
    const bodyW = 9.5;
    const bodyH = 6.5;
    const bodyX = x + 0.5;
    const bodyY = iconTop + 4.5;
    const centerX = x + 5.25;
    // 1. Shackle (Google Material rounded arch)
    ctx.lineWidth = 1.35;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.arc(centerX, iconTop + 2.8, 2.7, Math.PI, 0, false);
    ctx.lineTo(centerX + 2.7, bodyY + 0.5);
    ctx.moveTo(centerX - 2.7, iconTop + 2.8);
    ctx.lineTo(centerX - 2.7, bodyY + 0.5);
    ctx.stroke();
    // 2. Padlock Body
    ctx.beginPath();
    ctx.roundRect(bodyX, bodyY, bodyW, bodyH, 1.8);
    ctx.fill();
    // 3. Keyhole cutout (Google Material style)
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(centerX, bodyY + 2.3, 0.9, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillRect(centerX - 0.5, bodyY + 2.3, 1.0, 1.7);
    ctx.restore();
  }

  private static renderHeaders(
    ctx: CanvasRenderingContext2D,
    geometry: GeometryEngine,
    store: IDataStore,
    theme: IGridThemeTokens,
    scrollLeft: number,
    width: number,
    headerH: number,
    rowNumW: number,
    sortRules: SortDescriptor[],
    normSel: { minRow: number; maxRow: number; minCol: number; maxCol: number },
    hoveredFilterColIndex?: number | null,
    activeFilterColumnIds?: Set<string>,
    permissions?: GridPermissions,
    selectionMode: RowSelectionMode = 'none',
    selectedRowKeys?: Set<any>
  ): void {
    const rowCount = store.getRowCount();
    const hasGroups = geometry.hasColumnGroups;
    const groupH = hasGroups ? geometry.groupHeaderHeight : 0;
    const colHeaderH = hasGroups ? geometry.baseHeaderHeight : headerH;

    const totalLeftPinnedWidth = geometry.totalLeftPinnedWidth;
    const rightPinnedStartX = geometry.getRightPinnedStartX();
    const centerClipWidth = Math.max(0, rightPinnedStartX - totalLeftPinnedWidth);
    const rightClipWidth = Math.max(0, width - rightPinnedStartX);

    // ------------------------------------------------------------------------
    // PASS 1: CENTER SCROLLABLE HEADERS
    // ------------------------------------------------------------------------
    if (geometry.centerColumns.length > 0 && centerClipWidth > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(totalLeftPinnedWidth, 0, centerClipWidth, headerH);
      ctx.clip();

      ctx.fillStyle = theme.canvas.headerBg;
      ctx.fillRect(totalLeftPinnedWidth, 0, centerClipWidth, headerH);

      // 1a. Center Column Group Bands (Top Band)
      if (hasGroups) {
        this.renderColumnGroupBands(
          ctx,
          geometry.centerColumns,
          geometry.leftPinnedColumns.length,
          (idx) => totalLeftPinnedWidth + geometry.centerColOffsets[idx] - scrollLeft,
          groupH,
          theme,
          normSel,
          geometry,
          totalLeftPinnedWidth,
          rightPinnedStartX
        );
      }

      // 1b. Center Individual Column Headers
      for (let i = 0; i < geometry.centerColumns.length; i++) {
        const col = geometry.centerColumns[i];
        const colIdx = geometry.leftPinnedColumns.length + i;
        const x = totalLeftPinnedWidth + geometry.centerColOffsets[i] - scrollLeft;
        const groupDef = hasGroups ? geometry.getColumnGroup(col) : undefined;
        const colStyle = ColumnColorEngine.resolveColumnStyle(col, groupDef, theme.isDark);
        const colY = groupDef ? groupH : 0;
        const colH = groupDef ? colHeaderH : headerH;

        this.renderSingleHeader(
          ctx,
          col,
          colIdx,
          x,
          colY,
          col.width,
          colH,
          theme,
          sortRules,
          colIdx >= normSel.minCol && colIdx <= normSel.maxCol,
          hoveredFilterColIndex === colIdx,
          activeFilterColumnIds?.has(col.id) ?? false,
          store.isColumnDirty?.(col.id) ?? false,
          permissions,
          selectionMode,
          selectedRowKeys?.size || 0,
          rowCount,
          colStyle,
          Boolean(groupDef)
        );
      }
      ctx.restore();
    }

    // ------------------------------------------------------------------------
    // PASS 2: LEFT PINNED HEADERS & TOP-LEFT CORNER BOX
    // ------------------------------------------------------------------------
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, totalLeftPinnedWidth, headerH);
    ctx.clip();

    ctx.fillStyle = theme.canvas.headerBg;
    ctx.fillRect(0, 0, totalLeftPinnedWidth, headerH);

    const leftXOffsets: number[] = [];
    let accLeftX = rowNumW;
    for (let i = 0; i < geometry.leftPinnedColumns.length; i++) {
      leftXOffsets.push(accLeftX);
      accLeftX += geometry.leftPinnedColumns[i].width;
    }

    // 2a. Left Pinned Column Group Bands (Top Band)
    if (hasGroups && geometry.leftPinnedColumns.length > 0) {
      this.renderColumnGroupBands(
        ctx,
        geometry.leftPinnedColumns,
        0,
        (idx) => leftXOffsets[idx],
        groupH,
        theme,
        normSel,
        geometry,
        rowNumW,
        totalLeftPinnedWidth
      );
    }

    // 2b. Left Pinned Individual Column Headers
    let curLeftX = rowNumW;
    for (let i = 0; i < geometry.leftPinnedColumns.length; i++) {
      const col = geometry.leftPinnedColumns[i];
      const groupDef = hasGroups ? geometry.getColumnGroup(col) : undefined;
      const colStyle = ColumnColorEngine.resolveColumnStyle(col, groupDef, theme.isDark);
      const colY = groupDef ? groupH : 0;
      const colH = groupDef ? colHeaderH : headerH;

      this.renderSingleHeader(
        ctx,
        col,
        i,
        curLeftX,
        colY,
        col.width,
        colH,
        theme,
        sortRules,
        i >= normSel.minCol && i <= normSel.maxCol,
        hoveredFilterColIndex === i,
        activeFilterColumnIds?.has(col.id) ?? false,
        store.isColumnDirty?.(col.id) ?? false,
        permissions,
        selectionMode,
        selectedRowKeys?.size || 0,
        rowCount,
        colStyle,
        Boolean(groupDef)
      );
      curLeftX += col.width;
    }

    // 2c. Top-Left Corner Box (Select All)
    ctx.fillStyle = theme.canvas.rowNumberBg;
    ctx.fillRect(0, 0, rowNumW, headerH);
    ctx.strokeStyle = theme.canvas.headerBorder;
    ctx.strokeRect(0, 0, rowNumW, headerH);

    // Draw subtle corner triangle in top-left select-all box
    ctx.fillStyle = theme.isDark ? 'rgba(255,255,255,0.25)' : 'rgba(0,0,0,0.22)';
    ctx.beginPath();
    ctx.moveTo(rowNumW - 8, headerH - 16);
    ctx.lineTo(rowNumW - 8, headerH - 6);
    ctx.lineTo(rowNumW - 18, headerH - 6);
    ctx.closePath();
    ctx.fill();

    // Divider shadow on right edge of Left Pinned header
    if (geometry.leftPinnedColumns.length > 0) {
      ctx.fillStyle = theme.canvas.frozenDividerShadow;
      ctx.fillRect(totalLeftPinnedWidth - 1, 0, 3, headerH);
    }
    ctx.restore();

    // ------------------------------------------------------------------------
    // PASS 3: RIGHT PINNED HEADERS
    // ------------------------------------------------------------------------
    if (geometry.rightPinnedColumns.length > 0 && rightClipWidth > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(rightPinnedStartX, 0, rightClipWidth, headerH);
      ctx.clip();

      ctx.fillStyle = theme.canvas.headerBg;
      ctx.fillRect(rightPinnedStartX, 0, rightClipWidth, headerH);

      const baseRightIdx = geometry.leftPinnedColumns.length + geometry.centerColumns.length;

      // 3a. Right Pinned Column Group Bands (Top Band)
      if (hasGroups) {
        this.renderColumnGroupBands(
          ctx,
          geometry.rightPinnedColumns,
          baseRightIdx,
          (idx) => rightPinnedStartX + geometry.rightColOffsets[idx],
          groupH,
          theme,
          normSel,
          geometry,
          rightPinnedStartX,
          width
        );
      }

      // 3b. Right Pinned Individual Column Headers
      for (let i = 0; i < geometry.rightPinnedColumns.length; i++) {
        const col = geometry.rightPinnedColumns[i];
        const colIdx = baseRightIdx + i;
        const x = rightPinnedStartX + geometry.rightColOffsets[i];
        const groupDef = hasGroups ? geometry.getColumnGroup(col) : undefined;
        const colStyle = ColumnColorEngine.resolveColumnStyle(col, groupDef, theme.isDark);
        const colY = groupDef ? groupH : 0;
        const colH = groupDef ? colHeaderH : headerH;

        this.renderSingleHeader(
          ctx,
          col,
          colIdx,
          x,
          colY,
          col.width,
          colH,
          theme,
          sortRules,
          colIdx >= normSel.minCol && colIdx <= normSel.maxCol,
          hoveredFilterColIndex === colIdx,
          activeFilterColumnIds?.has(col.id) ?? false,
          store.isColumnDirty?.(col.id) ?? false,
          permissions,
          selectionMode,
          selectedRowKeys?.size || 0,
          rowCount,
          colStyle,
          Boolean(groupDef)
        );
      }

      // Divider shadow on left edge of Right Pinned header
      ctx.fillStyle = theme.canvas.frozenDividerShadow;
      ctx.fillRect(rightPinnedStartX - 2, 0, 3, headerH);
      ctx.restore();
    }
  }

  private static renderColumnGroupBands(
    ctx: CanvasRenderingContext2D,
    columns: ColumnDef[],
    colOffsetStartIdx: number,
    getColX: (localIdx: number) => number,
    groupH: number,
    theme: IGridThemeTokens,
    normSel: { minRow: number; maxRow: number; minCol: number; maxCol: number },
    geometry: GeometryEngine,
    minVisibleX: number = 0,
    maxVisibleX: number = 99999
  ): void {
    let i = 0;
    while (i < columns.length) {
      const col = columns[i];
      const groupDef = geometry.getColumnGroup(col);
      if (!groupDef) {
        i++;
        continue;
      }

      let j = i;
      let spanWidth = col.width;
      while (j + 1 < columns.length) {
        const nextGroup = geometry.getColumnGroup(columns[j + 1]);
        if (nextGroup && nextGroup.id === groupDef.id) {
          j++;
          spanWidth += columns[j].width;
        } else {
          break;
        }
      }

      const spanX = getColX(i);
      const startGlobalCol = colOffsetStartIdx + i;
      const endGlobalCol = colOffsetStartIdx + j;
      const isGroupActive =
        normSel.maxCol >= startGlobalCol && normSel.minCol <= endGlobalCol;

      const groupStyle = ColumnColorEngine.resolveGroupStyle(groupDef, theme.isDark);
      this.renderSingleGroupHeaderBand(
        ctx,
        groupDef,
        groupStyle,
        spanX,
        0,
        spanWidth,
        groupH,
        theme,
        isGroupActive,
        minVisibleX,
        maxVisibleX
      );

      i = j + 1;
    }
  }

  private static renderSingleGroupHeaderBand(
    ctx: CanvasRenderingContext2D,
    groupDef: ColumnGroupDef,
    groupStyle: ResolvedGroupHeaderStyle,
    x: number,
    y: number,
    w: number,
    h: number,
    theme: IGridThemeTokens,
    isGroupActive: boolean,
    minVisibleX: number = 0,
    maxVisibleX: number = 99999
  ): void {
    ctx.save();

    // 1. Group Band Background
    ctx.fillStyle =
      groupStyle.headerBg ||
      (theme.isDark ? 'rgba(255, 255, 255, 0.045)' : 'rgba(15, 23, 42, 0.04)');
    ctx.fillRect(x, y, w, h);

    if (isGroupActive && !groupStyle.headerBg) {
      ctx.fillStyle = theme.isDark ? 'rgba(10, 132, 255, 0.12)' : 'rgba(0, 122, 255, 0.07)';
      ctx.fillRect(x, y, w, h);
    }

    // 2. Top Accent Border (1px crisp hairline)
    const accentColor = groupStyle.headerAccent || (isGroupActive ? theme.dom.accentColor : undefined);
    if (accentColor) {
      ctx.save();
      ctx.globalAlpha = 0.65;
      ctx.fillStyle = accentColor;
      ctx.fillRect(x, y, w, 1);
      ctx.restore();
    }

    // 3. Borders (Right & Bottom Divider)
    ctx.strokeStyle = groupStyle.borderColor || theme.canvas.headerBorder;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + w - 0.5, y);
    ctx.lineTo(x + w - 0.5, y + h);
    ctx.moveTo(x, y + h - 0.5);
    ctx.lineTo(x + w, y + h - 0.5);
    ctx.stroke();

    // 4. Sticky Viewport-Clamped Group Title & Color Dot
    const visStart = Math.max(x, minVisibleX);
    const visEnd = Math.min(x + w, maxVisibleX);
    const visW = Math.max(0, visEnd - visStart);

    if (visW >= 24) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(visStart + 6, y, Math.max(0, visW - 12), h);
      ctx.clip();

      const textColor = groupStyle.headerText || theme.canvas.headerText;
      ctx.fillStyle = textColor;
      ctx.font = `700 ${Math.max(10, theme.headerFontSize - 1)}px ${theme.fontFamily}`;
      ctx.textBaseline = 'middle';

      const align = groupDef.align || 'center';
      const cy = y + h / 2 + 0.5;

      if (align === 'left') {
        let textX = visStart + 10;
        if (accentColor && visW >= 90) {
          ctx.beginPath();
          ctx.arc(textX + 3, cy, 3.2, 0, Math.PI * 2);
          ctx.fillStyle = accentColor;
          ctx.fill();
          textX += 11;
        }
        ctx.fillStyle = textColor;
        ctx.textAlign = 'left';
        ctx.fillText(groupDef.title, textX, cy);
      } else if (align === 'right') {
        ctx.textAlign = 'right';
        ctx.fillText(groupDef.title, visEnd - 10, cy);
      } else {
        ctx.textAlign = 'center';
        const titleMetrics = ctx.measureText(groupDef.title);
        const totalTitleW = titleMetrics.width;
        const centerX = visStart + visW / 2;
        if (accentColor && visW >= totalTitleW + 30) {
          const dotX = centerX - totalTitleW / 2 - 7;
          ctx.beginPath();
          ctx.arc(dotX, cy, 3.2, 0, Math.PI * 2);
          ctx.fillStyle = accentColor;
          ctx.fill();
          ctx.fillStyle = textColor;
          ctx.fillText(groupDef.title, centerX + 4, cy);
        } else if (visW < totalTitleW + 16) {
          ctx.textAlign = 'left';
          ctx.fillText(groupDef.title, visStart + 8, cy);
        } else {
          ctx.fillText(groupDef.title, centerX, cy);
        }
      }

      ctx.restore();
    }

    ctx.restore();
  }

  private static renderSingleHeader(
    ctx: CanvasRenderingContext2D,
    col: ColumnDef,
    _colIdx: number,
    x: number,
    y: number,
    w: number,
    h: number,
    theme: IGridThemeTokens,
    sortRules: SortDescriptor[],
    isColSelected: boolean,
    isFilterHovered: boolean,
    isFilterActive: boolean,
    isColumnDirty: boolean,
    permissions?: GridPermissions,
    selectionMode: RowSelectionMode = 'none',
    selectedCount: number = 0,
    totalRowCount: number = 0,
    colStyle?: ResolvedColumnStyle,
    hasParentGroup: boolean = false
  ): void {
    ctx.save();

    // Custom theme-aware column header background
    if (col.id !== '__selection__' && colStyle?.headerBg) {
      ctx.fillStyle = colStyle.headerBg;
      ctx.fillRect(x, y, w, h);
    }

    if (isColumnDirty) {
      ctx.fillStyle = theme.isDark ? 'rgba(34, 197, 94, 0.16)' : 'rgba(22, 163, 74, 0.12)';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = theme.isDark ? '#22C55E' : '#16A34A';
      ctx.fillRect(x, y, w, 1.5);
    } else if (isColSelected) {
      ctx.fillStyle = theme.isDark ? 'rgba(10, 132, 255, 0.12)' : 'rgba(0, 122, 255, 0.07)';
      ctx.fillRect(x, y, w, h);
    }

    // Top accent border on ungrouped colored column headers (1px crisp hairline)
    if (!isColumnDirty && !hasParentGroup && colStyle?.headerAccent && col.id !== '__selection__') {
      ctx.save();
      ctx.globalAlpha = 0.65;
      ctx.fillStyle = colStyle.headerAccent;
      ctx.fillRect(x, y, w, 1);
      ctx.restore();
    }

    // Borders
    ctx.strokeStyle = colStyle?.borderColor || theme.canvas.headerBorder;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + w - 0.5, y);
    ctx.lineTo(x + w - 0.5, y + h);
    ctx.moveTo(x, y + h - 0.5);
    ctx.lineTo(x + w, y + h - 0.5);
    ctx.stroke();

    // Synthetic Row Selection Header ('__selection__')
    if (col.id === '__selection__') {
      const cx = x + w / 2;
      const cy = y + h / 2;
      if (selectionMode === 'single') {
        ctx.beginPath();
        ctx.arc(cx, cy, 7, 0, Math.PI * 2);
        ctx.strokeStyle = theme.canvas.headerText;
        ctx.lineWidth = 1.5;
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(cx, cy, 2.5, 0, Math.PI * 2);
        ctx.fillStyle = theme.canvas.headerText;
        ctx.fill();
      } else {
        const boxSize = 15;
        const bx = cx - boxSize / 2;
        const by = cy - boxSize / 2;
        const isAllSelected = totalRowCount > 0 && selectedCount >= totalRowCount;
        const isSomeSelected = selectedCount > 0 && selectedCount < totalRowCount;
        ctx.beginPath();
        ctx.roundRect(bx, by, boxSize, boxSize, 4);
        if (isAllSelected || isSomeSelected) {
          ctx.fillStyle = theme.dom.accentColor;
          ctx.fill();
          ctx.strokeStyle = '#FFFFFF';
          ctx.lineWidth = 2;
          ctx.beginPath();
          if (isAllSelected) {
            ctx.moveTo(bx + 3.5, cy);
            ctx.lineTo(bx + 6.5, cy + 3);
            ctx.lineTo(bx + 11.5, cy - 3);
          } else {
            ctx.moveTo(bx + 3.5, cy);
            ctx.lineTo(bx + 11.5, cy);
          }
          ctx.stroke();
        } else {
          ctx.fillStyle = theme.dom.inputBg;
          ctx.fill();
          ctx.strokeStyle = theme.canvas.headerBorder;
          ctx.lineWidth = 1.4;
          ctx.stroke();
        }
      }
      ctx.restore();
      return;
    }

    // Active column bottom highlight bar
    if (isColSelected) {
      ctx.fillStyle = colStyle?.headerAccent || theme.dom.accentColor;
      ctx.fillRect(x, y + h - 2, w, 2);
    }

    const isReadonly = this.isColumnReadonly(col, permissions);
    const isFilterable =
      col.filterable !== false && col.type !== 'sparkline' && col.type !== 'action';
    const sortIndex = sortRules.findIndex((s) => s.selector === col.id);

    const rightReserved = (isFilterable ? 28 : 8) + (sortIndex !== -1 ? 18 : 0);

    // Header Title + Optional Readonly Lock Icon
    ctx.save();
    ctx.beginPath();
    ctx.rect(x + 8, y, Math.max(0, w - rightReserved - 8), h);
    ctx.clip();

    ctx.fillStyle = colStyle?.headerText || theme.canvas.headerText;
    ctx.font = `600 ${theme.headerFontSize}px ${theme.fontFamily}`;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    let titleX = x + 8;
    if (isReadonly && col.type !== 'action' && col.type !== 'sparkline' && !col.onCellClick && !col.hideLockIcon) {
      const lockColor = colStyle?.headerAccent || (theme.isDark ? '#fbbf24' : '#d97706');
      CanvasRenderer.drawGoogleLockIcon(ctx, titleX, y + h / 2, lockColor);
      titleX += 14;
    }
    const safeTitle = typeof col.title === 'string' && col.title.trim() !== '' ? col.title : (col.id === 'constructor' ? 'Constructor' : String(col.id || ''));
    ctx.fillText(safeTitle, titleX, y + h / 2);
    ctx.restore();

    // Sort Arrow
    if (sortIndex !== -1) {
      const sort = sortRules[sortIndex];
      ctx.save();
      ctx.fillStyle = colStyle?.headerAccent || theme.dom.accentColor;
      ctx.font = `700 10px ${theme.fontFamily}`;
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      const arrow = sort.desc ? '▼' : '▲';
      const badge = sortRules.length > 1 ? `${arrow}${sortIndex + 1}` : arrow;
      ctx.fillText(badge, x + w - (isFilterable ? 28 : 8), y + h / 2);
      ctx.restore();
    }

    // Filter Funnel Button (Easy-to-click 22x22 button box)
    if (isFilterable && w >= 48) {
      const btnSize = 20;
      const btnX = x + w - btnSize - 5;
      const btnY = y + (h - btnSize) / 2;

      ctx.save();
      if (isFilterActive) {
        ctx.fillStyle = colStyle?.headerAccent || theme.dom.accentColor;
        ctx.beginPath();
        ctx.roundRect(btnX, btnY, btnSize, btnSize, 5);
        ctx.fill();
      } else if (isFilterHovered) {
        ctx.fillStyle = theme.isDark ? 'rgba(255,255,255,0.14)' : 'rgba(0,0,0,0.08)';
        ctx.beginPath();
        ctx.roundRect(btnX, btnY, btnSize, btnSize, 5);
        ctx.fill();
      }

      const fx = btnX + btnSize / 2;
      const fy = btnY + btnSize / 2;
      ctx.fillStyle = isFilterActive
        ? '#FFFFFF'
        : isFilterHovered
          ? colStyle?.headerText || theme.canvas.headerText
          : colStyle?.headerText
            ? colStyle.headerText
            : theme.isDark
              ? '#98989D'
              : '#8E8E93';
      if (!isFilterActive && !isFilterHovered && colStyle?.headerText) {
        ctx.globalAlpha = 0.72;
      }

      ctx.beginPath();
      ctx.moveTo(fx - 5, fy - 4);
      ctx.lineTo(fx + 5, fy - 4);
      ctx.lineTo(fx + 1.5, fy + 0.5);
      ctx.lineTo(fx + 1.5, fy + 4.5);
      ctx.lineTo(fx - 1.5, fy + 3.5);
      ctx.lineTo(fx - 1.5, fy + 0.5);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  /**
   * Paints a full-width Group Row Band with expand/collapse toggle and level indentation.
   */
  public static paintGroupRowBand(
    ctx: CanvasRenderingContext2D,
    row: any,
    y: number,
    width: number,
    height: number,
    theme: IGridThemeTokens,
    locale: IGridLocale,
    columns?: ColumnDef[],
    isHovered?: boolean,
    rowNumW: number = 54
  ): void {
    ctx.save();

    // 1. Full-width Group Row Band Background (slightly darker like header / groupRowBg)
    ctx.fillStyle = isHovered
      ? theme.isDark
        ? 'rgba(56, 189, 248, 0.16)'
        : 'rgba(2, 132, 199, 0.10)'
      : theme.canvas.groupRowBg || theme.canvas.headerBg;
    ctx.fillRect(0, y, width, height);

    // 2. Bottom Border
    ctx.strokeStyle = theme.canvas.groupRowBorder || theme.canvas.headerBorder;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, y + height - 0.5);
    ctx.lineTo(width, y + height - 0.5);
    ctx.stroke();

    const level = row.level ?? 0;
    const isExpanded = Boolean(row.isExpanded);
    const field = row.groupField || row.field || '';
    const val = row.groupValue !== undefined ? row.groupValue : (row.value ?? '');
    const count = row.childrenCount ?? row.rowCount ?? 0;

    // 3. Left Accent Bar by Level
    ctx.fillStyle = theme.dom.accentColor;
    ctx.fillRect(level * 6, y, 4, height);

    // 4. Expand/Collapse toggle ([-] or [+])
    // Indent the text and icon horizontally based on row.level
    const leftOffset = Math.max(rowNumW, 20);
    const indent = leftOffset + (level * 20);
    const midY = y + height / 2;
    const boxSize = 16;

    ctx.fillStyle = isExpanded
      ? theme.dom.accentColor
      : theme.isDark
      ? 'rgba(255,255,255,0.12)'
      : 'rgba(0,0,0,0.08)';
    ctx.beginPath();
    ctx.roundRect(indent - boxSize / 2, midY - boxSize / 2, boxSize, boxSize, 3);
    ctx.fill();

    ctx.fillStyle = isExpanded ? '#FFFFFF' : theme.canvas.groupRowText;
    ctx.font = `700 13px ${theme.fontFamily}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(isExpanded ? '−' : '+', indent, midY);

    // 5. Group Title: `${row.groupField}: ${row.groupValue} (${row.childrenCount})`
    const colDef = columns?.find((c) => c.id === field);
    const colTitle = colDef ? colDef.title.replace(' ⚡', '') : field.toUpperCase();
    const displayVal = String(val ?? (locale?.emptyText || '(Blank)'));
    const title = `${colTitle}: ${displayVal} (${count})`;

    ctx.fillStyle = theme.canvas.groupRowText;
    ctx.font = `700 ${theme.fontSize}px ${theme.fontFamily}`;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(title, indent + boxSize / 2 + 10, midY);

    // 6. Optional Column Aggregations on Right Side
    const aggs = row.aggregations || row.summaries;
    if (aggs && Object.keys(aggs).length > 0) {
      const summaryText = Object.entries(aggs)
        .slice(0, 4)
        .map(([k, v]) => {
          const sCol = columns?.find((c) => c.id === k);
          const sTitle = sCol ? sCol.title.replace(' ⚡', '') : k;
          const numStr = Number(v).toLocaleString(locale?.code || 'en-US', {
            maximumFractionDigits: 2,
          });
          return `${sTitle}: ${sCol?.currencySymbol || ''}${numStr}`;
        })
        .join('   •   ');

      ctx.fillStyle = theme.isDark ? '#98989D' : '#6E6E73';
      ctx.font = `600 ${theme.fontSize - 1}px ${theme.fontFamily}`;
      ctx.textAlign = 'right';
      ctx.fillText(summaryText, width - 24, midY);
    }

    ctx.restore();
  }
}
